// equivalent_expressions — 수치 단답(SPR 가능) hard 원형 3 kind × 4 연산자 × 4 변형. 식의 동치·전개·지수·항등식에서 정답이 하나의 수가 되는 문항(기존 식 선지형 원형과 별개).
import { GenFail } from "../types";
import { need, isInt, sp, mkKind, pickDiv, type Var } from "./spr-a-kit";
import { poly, shifted, M } from "../text";
import type { Rng } from "../rng";
