const dress = (vs: Var[]): Var[] => vs;
const MUL = "const mul = (p, q) => { const r = Array(p.length + q.length - 1).fill(0); p.forEach((a, i) => q.forEach((b, j) => { r[i + j] += a * b; })); return r; };\n";
